import { adviceAddBundle, adviceAddItem } from "#base/ui/advice/advice-manager.js";
import { shouldSelect } from "#base/ui/advice/advice-support.js";

const TURN_WAIT = 20; // auto-select next item every so many turns.
const TURN_START = 10; // On which turn should items start being selected (phased by turn offset).
const TURN_OFFSET = 12; // Which "phase" (from turn 1) to start checking.

adviceAddItem({
	id: "ADVICE_MODERN_MILITARY_MILITARY_VICTORY",
	type: AdvisorTypes.MILITARY,
	onSelect: () => {
		return Game.turn == 1;
	},
});

adviceAddBundle({
	id: "ADVICE_MODERN_MILITARY_MISC",
	type: AdvisorTypes.MILITARY,
	pages: [
		"ADVICE_MODERN_MILITARY_VICTORY_COUNTERPLAY",
		"ADVICE_MODERN_MILITARY_IDEOLOGIES",
		"ADVICE_MODERN_MILITARY_AIR_COMBAT",
		"ADVICE_MODERN_MILITARY_TRIUMPH",
	],
	priority: 100,
	delivery: "random",
	onSelect: () => {
		return shouldSelect(TURN_START, TURN_WAIT, TURN_OFFSET);
	},
});
